    private static DocumentBlock Node(string name, Formula formula, string prose, DescribeRole role, AssessedProvenance provenance) =>
        Describe.Lean(DescribeId.Create("passive-fock-" + name.Replace('_', '-').ToLowerInvariant()), DeclarationHandle.Create(Prefix + name), H(name.Replace('_', ' ')), StatementSource.FromAuthor(Disp(formula)), provenance, Blocks(Paragraph(Text(prose))), role);
    private static Formula Parenthesized(Formula value) => Seq(Open, value, Close);
    private static Formula X(string s) => F.Id(s);
    private static Formula Q(string s)
    {
        var parts = s.Split('.');
        var tokens = new List<Formula>();
        foreach (var part in parts)
        {
            if (tokens.Count != 0) tokens.Add(Dot);
            tokens.Add(F.Id(part));
        }
        return Seq(Operatorname, Grp(Seq([.. tokens])));
    }
    private static Formula Call(string s, params Formula[] xs) => new Formula.Apply(Q(s), [.. xs]);
    private static Formula At(Formula f, params Formula[] xs) => new Formula.Apply(f, [.. xs]);
    private static Formula All(string s, Formula t, Formula b) => Seq(Forall, Sp, Parenthesized(Seq(X(s), Sp, Colon, Sp, t)), Comma, Sp, Parenthesized(b));
    private static Formula Lam(string s, Formula t, Formula b) => Seq(Parenthesized(Seq(X(s), Sp, Colon, Sp, t)), Sp, Mapsto, Sp, Parenthesized(b));
    private static Formula Eqn(Formula a, Formula b) => new Formula.Relation(a, FormulaRelationOperator.Equal, b);
    private static Formula Ne(Formula a, Formula b) => new Formula.Relation(a, FormulaRelationOperator.NotEqual, b);
    private static Formula Imp(Formula a, Formula b) => new Formula.Logic(Parenthesized(a), FormulaLogicOperator.Implies, Parenthesized(b));
    private static Formula Add(Formula a, Formula b) => new Formula.Binary(a, FormulaBinaryOperator.Add, b);
    private static Formula Mul(Formula a, Formula b) => new Formula.Binary(Parenthesized(a), FormulaBinaryOperator.Multiply, Parenthesized(b));
    private static Formula Pow(Formula a, Formula b) => new Formula.Power(Parenthesized(a), b);
    private static Formula Div(Formula a, Formula b) => new Formula.Fraction(a, b);
    private static Formula Norm(Formula a) => new Formula.Norm(a);
    private static Formula Smul(Formula a, Formula b) => Seq(Parenthesized(a), Sp, Cdot, Sp, Parenthesized(b));
    private static Formula Nat() => Seq(Mathbb, Grp(X("N")));
    private static Formula Complex() => Seq(Mathbb, Grp(X("C")));
    private static Formula Iso(Formula a) => Call("LinearIsometryEquiv", Complex(), a, a);
    private static Formula ModeSpace(Formula k) => Call("EuclideanSpace", Complex(), Call("Fin", k));
    private static Formula Fock(Formula k) => Call("Fock", k);
    private static Formula Succ(Formula k) => Add(k, D(1));
    private static Formula Inner(Formula a, Formula b) => Call("inner", Complex(), a, b);
    private static Formula Cast(Formula a, Formula t) => Parenthesized(Seq(a, Sp, Colon, Sp, t));
    private static Formula Inst(string s, Formula t) => Seq(OpenBracket, Call(s, t), CloseBracket, Sp);
    private static Formula WithK(Formula b) => All("k", Nat(), b);
    private static Formula Exp(Formula k, Formula b) => Call("exponential", k, b);
    private static Formula One(Formula k, Formula b) => Call("onePhoton", k, b);
    private static Formula Normalization(Formula b) => Cast(Call("Real.exp", Div(new Formula.Negate(Pow(Norm(b), D(2))), D(2))), Complex());
    private static Formula K => X("k");
    private static Formula B => X("beta");
    private static Formula G => X("gamma");
    private static Formula V => X("v");
    private static Formula A => X("alpha");
    private static Formula N => X("n");
    private static Formula M => X("m");
